html:
{%- set proposal = doc -%}
{%- set ctx = proposal.get_devis_context() -%}
{%- set project = ctx.project -%}
{%- set agency = ctx.agency -%}
{%- set client = ctx.client -%}
{%- set client_name = ctx.client_name -%}
{%- set items = ctx["quote_items"] -%}
{%- set total_ht = ctx.total_ht -%}
{%- set vat_rate = ctx.vat_rate -%}
{%- set total_vat = ctx.total_vat -%}
{%- set total_ttc = ctx.total_ttc -%}
{%- set generated_at = ctx.generated_at -%}
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Devis {{ proposal.name }}</title>
<style>
	body { font-family: "Helvetica Neue", Arial, sans-serif; color: #1f2933; font-size: 12px; margin: 0; padding: 20px; background: #f5f6f8; }
	.page { max-width: 720px; margin: 0 auto; background: #ffffff; border: 1px solid #d2d6dc; border-radius: 10px; padding: 34px; }

	table.header-table { width: 100%; border-collapse: collapse; margin-bottom: 4px; }
	table.header-table td { vertical-align: top; width: 50%; font-size: 11.5px; line-height: 1.65; }
	table.header-table td.client-cell { text-align: right; }
	.agency-name { display: block; font-size: 15px; font-weight: bold; letter-spacing: -0.01em; margin-bottom: 4px; }
	.client-label { display: block; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.08em; color: #9aa5b1; margin-bottom: 3px; }

	.badge-row { display: flex; justify-content: flex-end; margin: 10px 0 6px 0; }
	.badge { display: inline-block; background: #1f2933; color: #ffffff; font-size: 10px; font-weight: bold;
		letter-spacing: 0.08em; text-transform: uppercase; padding: 5px 12px; border-radius: 4px; }

	.accent-line { height: 2px; background: #1f2933; margin: 14px 0 18px 0; border-radius: 1px; }

	h1 { font-size: 14px; margin: 0 0 3px 0; }
	.legal-note { color: #9aa5b1; font-size: 9.5px; margin: 0 0 16px 0; }

	table.items { width: 100%; border-collapse: collapse; margin-top: 6px; border: 1px solid #1f2933; border-radius: 4px; overflow: hidden; }
	table.items th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em;
		background: #1f2933; color: #ffffff; padding: 8px 10px; }
	table.items th.num, table.items td.num { text-align: right; }
	table.items td { padding: 9px 10px; border-bottom: 1px solid #e4e7eb; vertical-align: top; font-size: 11.5px; }
	table.items tr:last-child td { border-bottom: none; }
	table.items td .details { display: block; color: #9aa5b1; font-size: 10px; font-style: italic; margin-top: 2px; }

	table.bottom-table { width: 100%; border-collapse: collapse; margin-top: 22px; }
	table.bottom-table td { vertical-align: top; width: 50%; }
	table.bottom-table .left-info p { margin: 5px 0; font-size: 11px; color: #3e4c59; }
	table.bottom-table .left-info p strong { color: #1f2933; }

	table.totals { border-collapse: collapse; margin-left: auto; min-width: 220px; }
	table.totals td { padding: 7px 14px; font-size: 11.5px; border-bottom: 1px solid #e4e7eb; }
	table.totals td.label { color: #616e7c; }
	table.totals td.num { text-align: right; }
	table.totals tr.grand-total { background: #f5f7fa; }
	table.totals tr.grand-total td { font-weight: bold; font-size: 13px; border-bottom: none; padding-top: 9px; padding-bottom: 9px; }

	.footer { margin-top: 36px; padding-top: 16px; border-top: 1px solid #e4e7eb; font-size: 11px; }
	.footer .validity { color: #9aa5b1; font-size: 10px; margin-top: 14px; }
</style>
</head>
<body>
<div class="page">
	<table class="header-table">
		<tr>
			<td>
				<span class="agency-name">{{ agency.agency_name or "Nom de l'entreprise" }}</span>
				{{ agency.location or "—" }}<br>
				{{ agency.legal_id_label or "Forme juridique" }} : {{ agency.legal_id or "—" }}<br>
				Numéro de TVA : —<br>
				Tél : {{ agency.phone or "—" }}<br>
				Email : {{ agency.email or "—" }}
			</td>
			<td class="client-cell">
				<span class="client-label">Destinataire</span>
				{{ client_name }}<br>
				{{ client.country or "" }}
			</td>
		</tr>
	</table>

	<div class="badge-row"><span class="badge">Devis {{ proposal.name }}</span></div>
	<div class="accent-line"></div>

	<h1>Objet : "{{ project.title }}"</h1>
	<p class="legal-note">Dispensé d'immatriculation au registre du commerce et des sociétés (RCS) et au répertoire des métiers (RM)</p>

	<table class="items">
		<thead>
			<tr>
				<th>Désignation</th>
				<th class="num">Qté</th>
				<th class="num">PU HT</th>
				<th class="num">Total HT</th>
			</tr>
		</thead>
		<tbody>
			{% for item in items %}
			<tr>
				<td>
					{{ item.designation }}
					{% if item.details %}<span class="details">{{ item.details }}</span>{% endif %}
				</td>
				<td class="num">{{ "%.2f"|format(item.quantity) }}</td>
				<td class="num">{{ "%.2f"|format(item.unit_price) }} €</td>
				<td class="num">{{ "%.2f"|format(item.quantity * item.unit_price) }} €</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>

	<table class="bottom-table">
		<tr>
			<td class="left-info">
				<p><strong>Date du devis</strong> : {{ generated_at }}</p>
				<p><strong>Durée de validité</strong> : 30 jours</p>
				<p><strong>Mode de paiement</strong> : Virement</p>
			</td>
			<td>
				<table class="totals">
					<tr><td class="label">Montant HT</td><td class="num">{{ "%.2f"|format(total_ht) }} €</td></tr>
					<tr><td class="label">TVA à {{ "%.0f"|format(vat_rate) }} %</td><td class="num">{{ "%.2f"|format(total_vat) }} €</td></tr>
					<tr class="grand-total"><td class="label">Montant TTC</td><td class="num">{{ "%.2f"|format(total_ttc) }} €</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<div class="footer">
		Bon pour accord le : ______________________<br><br>
		Signature :
		<p class="validity">Ce devis est valable 30 jours à compter de sa date d'émission. Généré depuis Sortlist.</p>
	</div>
</div>
</body>
</html>
